965	func (ea *ExpressionAttribute) formatExpression() (exp []string) {
966		trimmed := strings.TrimSpace(ea.Expression.Value)
967		if !strings.Contains(trimmed, "\n") {
968			formatted, err := format.Source([]byte(trimmed))
969			if err != nil {
970				return []string{trimmed}
971			}
972			return []string{string(formatted)}
973		}
974	
975		buf := bytes.NewBufferString("[]any{\n")
976		buf.WriteString(trimmed)
977		buf.WriteString("\n}")
978	
979		formatted, err := format.Source(buf.Bytes())
980		if err != nil {
981			return []string{trimmed}
982		}
983	
984		// Trim prefix and suffix.
985		lines := strings.Split(string(formatted), "\n")
986		if len(lines) < 3 {
987			return []string{trimmed}
988		}
989	
990		// Return.
991		return lines[1 : len(lines)-1]
992	}
